# <<< SPEC

# >>> HINTS
# <<< HINTS

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_dependency() {
    if [[ -n "${argc_global:-}" ]]; then
        _helper_global_packages
    else
        _helper_local_packages
    fi
}

_choice_exec() {
    _helper_local_package_bins
    _helper_cached_package_bins
}

_choice_exec_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_exec
        return 0
    fi
    local package="${argc__positionals[0]}"
    case "$package" in
        @*/*@*) package="${package%@*}" ;;
        @*) ;;
        *@*) package="${package%@*}" ;;
    esac
    argc__positionals[0]="$package"
    _argc_util_comp_subcommand 0
}

_choice_run() {
    local pkg
    pkg="$(_argc_util_path_search_parent package.json)" || return 0
    [[ -n "$pkg" ]] || return 0
    jq -b -r '(.scripts // {}) | keys[]' "$pkg" 2>/dev/null
}

_choice_workspace() {
    npm query .workspace | jq -b -r '.[].location'
}

_helper_cached_package_bins() {
    local base dir
    for base in "${HOME:-}/.npm/_npx" "${LOCALAPPDATA:-}/npm-cache/_npx"; do
        base="${base//\\//}"
        for dir in "$base"/*/node_modules/.bin; do
            [[ -d "$dir" ]] || continue
            _helper_list_bins "$dir"
        done
    done | gawk '!seen[$0]++' | head -n 200
}

_helper_global_packages() {
    local root dir name sub
    root="$(npm root -g 2>/dev/null)" || return 0
    root="${root//\\//}"
    [[ -n "$root" && -d "$root" ]] || return 0
    for dir in "$root"/*; do
        [[ -d "$dir" ]] || continue
        name="${dir##*/}"
        if [[ "$name" == @* ]]; then
            for sub in "$dir"/*; do
                [[ -d "$sub" ]] || continue
                printf '%s\n' "$name/${sub##*/}"
            done
        else
            printf '%s\n' "$name"
        fi
    done
}

_helper_list_bins() {
    local dir="$1" bin name
    for bin in "$dir"/*; do
        [[ -e "$bin" ]] || continue
        name="${bin##*/}"
        case "$name" in
            *.cmd|*.ps1) continue ;;
        esac
        printf '%s\n' "$name"
    done
}

_helper_local_package_bins() {
    local pkg dir
    pkg="$(_argc_util_path_search_parent package.json)" || return 0
    [[ -n "$pkg" ]] || return 0
    dir="${pkg%/package.json}/node_modules/.bin"
    [[ -d "$dir" ]] || return 0
    _helper_list_bins "$dir"
}

_helper_local_packages() {
    local pkg
    pkg="$(_argc_util_path_search_parent package.json)" || return 0
    [[ -n "$pkg" ]] || return 0
    jq -b -r '[(.dependencies // {}), (.devDependencies // {}), (.optionalDependencies // {}), (.peerDependencies // {})]
        | map(keys) | add // [] | .[]' "$pkg" 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
